{
  "name": "@juanzea/ptp-studio-mcp",
  "version": "0.7.1",
  "description": "Companion MCP local de PTP Studio: expone tus sitios y entornos guardados a un agente de IA y opera la app en vivo (crear/consultar/cancelar sesiones de pago, navegar, configurar). Delega el checkout de Webcheckout por HTTP.",
  "type": "module",
  "license": "MIT",
  "author": "Juan Zea (https://github.com/JuanZea)",
  "homepage": "https://github.com/JuanZea/ptp-studio-mcp#readme",
  "repository": {
    "type": "git",
    "url": "git+https://github.com/JuanZea/ptp-studio-mcp.git"
  },
  "bugs": {
    "url": "https://github.com/JuanZea/ptp-studio-mcp/issues"
  },
  "keywords": [
    "mcp",
    "model-context-protocol",
    "placetopay",
    "webcheckout",
    "ptp-studio",
    "claude",
    "opencode"
  ],
  "bin": {
    "ptp-studio-mcp": "src/server.mjs"
  },
  "files": [
    "src",
    ".env.example",
    "README.md",
    "LICENSE"
  ],
  "scripts": {
    "start": "node src/server.mjs"
  },
  "engines": {
    "node": ">=20"
  },
  "publishConfig": {
    "access": "public"
  },
  "dependencies": {
    "@modelcontextprotocol/sdk": "1.29.0",
    "ws": "8.21.1"
  }
}
